import{_ as e,c as r,o as n,a2 as a}from"./chunks/framework.CIiVzG-O.js";const x=JSON.parse('{"title":"支援格式","description":"","frontmatter":{},"headers":[],"relativePath":"zh-TW/guide/formats.md","filePath":"zh-TW/guide/formats.md","lastUpdated":1793163976000}'),l={name:"zh-TW/guide/formats.md"};function d(s,t,i,o,g,c){return n(),r("div",null,[...t[0]||(t[0]=[a('<h1 id="支援格式" tabindex="-1">支援格式 <a class="header-anchor" href="#支援格式" aria-label="Permalink to &quot;支援格式&quot;">​</a></h1><p>NueZip 支援多種壓縮檔格式的讀取與寫入。以下是完整的格式相容性對照表。</p><h2 id="格式對照表" tabindex="-1">格式對照表 <a class="header-anchor" href="#格式對照表" aria-label="Permalink to &quot;格式對照表&quot;">​</a></h2><table tabindex="0"><thead><tr><th>格式</th><th style="text-align:center;">讀取</th><th style="text-align:center;">寫入（壓縮）</th><th style="text-align:center;">加密</th><th style="text-align:center;">多分割卷</th></tr></thead><tbody><tr><td><strong>ZIP</strong></td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td style="text-align:center;">AES-256</td><td style="text-align:center;">✅</td></tr><tr><td><strong>7-Zip (.7z)</strong></td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td style="text-align:center;">AES-256 (LZMA2)</td><td style="text-align:center;">✅</td></tr><tr><td><strong>TAR</strong></td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td style="text-align:center;">—</td><td style="text-align:center;">✅</td></tr><tr><td><strong>GZIP (.gz)</strong></td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td style="text-align:center;">—</td><td style="text-align:center;">—</td></tr><tr><td><strong>BZIP2 (.bz2)</strong></td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td style="text-align:center;">—</td><td style="text-align:center;">—</td></tr><tr><td><strong>XZ</strong></td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td style="text-align:center;">—</td><td style="text-align:center;">—</td></tr><tr><td><strong>Zstandard (.zst)</strong></td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td style="text-align:center;">—</td><td style="text-align:center;">—</td></tr><tr><td><strong>RAR</strong></td><td style="text-align:center;">✅</td><td style="text-align:center;">❌</td><td style="text-align:center;">✅ (讀取)</td><td style="text-align:center;">✅ (讀取)</td></tr></tbody></table><blockquote><p><strong>注意</strong>：基於授權限制，不支援 RAR 壓縮。NueZip 可以讀取 RAR 壓縮檔，包括多分割卷與加密的 RAR 壓縮檔。</p></blockquote><h2 id="格式詳細說明" tabindex="-1">格式詳細說明 <a class="header-anchor" href="#格式詳細說明" aria-label="Permalink to &quot;格式詳細說明&quot;">​</a></h2><h3 id="zip" tabindex="-1">ZIP <a class="header-anchor" href="#zip" aria-label="Permalink to &quot;ZIP&quot;">​</a></h3><ul><li><strong>壓縮</strong>：Store、Deflate、Deflate64、BZIP2、LZMA、PPMd</li><li><strong>加密</strong>：AES-256（建議）、ZipCrypto（舊式）</li><li><strong>卷支援</strong>：多分割卷壓縮檔（<code>.zip.001</code>、<code>.zip.002</code>、...）</li><li><strong>最適用於</strong>：跨平台的最廣泛相容性</li></ul><h3 id="_7-zip" tabindex="-1">7-Zip <a class="header-anchor" href="#_7-zip" aria-label="Permalink to &quot;7-Zip&quot;">​</a></h3><ul><li><strong>壓縮</strong>：LZMA2（預設）、LZMA、PPMd、BZIP2、Deflate</li><li><strong>加密</strong>：AES-256</li><li><strong>卷支援</strong>：多分割卷壓縮檔</li><li><strong>最適用於</strong>：最大壓縮比</li></ul><h3 id="tar" tabindex="-1">TAR <a class="header-anchor" href="#tar" aria-label="Permalink to &quot;TAR&quot;">​</a></h3><ul><li><strong>壓縮</strong>：未壓縮，或結合 GZIP/BZIP2/XZ/Zstandard</li><li><strong>最適用於</strong>：Unix/Linux 封存檔，保留檔案權限</li></ul><h3 id="gzip-bzip2-xz-zstandard" tabindex="-1">GZIP / BZIP2 / XZ / Zstandard <a class="header-anchor" href="#gzip-bzip2-xz-zstandard" aria-label="Permalink to &quot;GZIP / BZIP2 / XZ / Zstandard&quot;">​</a></h3><ul><li><strong>獨立</strong> 壓縮格式（單一檔案，無封存打包）</li><li>常與 TAR 搭配使用（<code>.tar.gz</code>、<code>.tar.xz</code>、<code>.tar.zst</code>）</li></ul><h3 id="rar" tabindex="-1">RAR <a class="header-anchor" href="#rar" aria-label="Permalink to &quot;RAR&quot;">​</a></h3><ul><li><strong>讀取支援</strong>：RAR4、RAR5、多分割卷、加密</li><li><strong>修復</strong>：復原記錄與重建</li><li><strong>寫入</strong>：不支援</li></ul><h2 id="小訣竅" tabindex="-1">小訣竅 <a class="header-anchor" href="#小訣竅" aria-label="Permalink to &quot;小訣竅&quot;">​</a></h2><ul><li><strong>與他人分享時</strong>：使用 <strong>ZIP</strong> — 這是最廣泛相容的格式</li><li><strong>個人封存時</strong>：使用 <strong>7-Zip</strong> — 最佳壓縮比，節省磁碟空間</li><li><strong>針對大型檔案</strong>：使用 <strong>分割 ZIP</strong> 或 <strong>分割 7-Zip</strong> 拆分成易於管理的卷</li><li><strong>針對敏感資料</strong>：一律啟用 <strong>AES-256 加密</strong> 並搭配強密碼</li></ul>',18)])])}const u=e(l,[["render",d]]);export{x as __pageData,u as default};
